import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { loginUser } from '../services/api';

const Login = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    try {
      const res = await loginUser({ username, password });
      const { token } = res.data;
      localStorage.setItem('auth_token', token);
      navigate('/');
    } catch (err) {
      setError(err.response?.data?.error || 'Login failed');
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <form onSubmit={handleSubmit} className="bg-white p-8 rounded shadow w-full max-w-md">
        <h3 className="text-lg font-semibold mb-4">Sign in</h3>
        {error && <div className="text-sm text-red-600 mb-2">{error}</div>}
        <label className="block text-sm">Username</label>
        <input value={username} onChange={e => setUsername(e.target.value)} className="w-full border p-2 rounded mb-3" />
        <label className="block text-sm">Password</label>
        <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full border p-2 rounded mb-4" />
        <button className="w-full bg-primary text-white py-2 rounded">Login</button>
        <p className="text-xs text-slate-500 mt-3">No account? <Link to="/register" className="text-primary">Register</Link></p>
      </form>
    </div>
  );
};

export default Login;
